    "keywords": [
      "sell tenanted property Dubai",
      "selling property with tenant Dubai",
      "vacant possession Dubai",
      "12 month notice tenant Dubai",
      "buyer inherits lease Dubai",
      "Ejari sale",
      "RERA rental index",
      "selling occupied property Dubai"
    ],
